export function toolFeedbackCss(){return `.tt-tool-measure{display:inline-flex;gap:4px;font:11px var(--font-mono,monospace);white-space:nowrap}.tt-measure-added{color:var(--dsw-alias-state-success-primary,#22c55e)}.tt-measure-removed{color:var(--dsw-alias-state-error-primary,#ec1313)}.tt-measure-muted{color:var(--muted,#777)}.tt-feedback-peek{display:block;font-size:12px;line-height:1.5;color:var(--muted,#777);max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:6px}.tt-feedback-peek b{color:#b84b50;font:11px var(--font-mono,monospace);font-weight:500}.tt-code-feedback{margin:15px 0;font-size:12px;min-width:0}.tt-code-feedback header{display:flex;gap:12px;flex-wrap:wrap;align-items:baseline;margin-bottom:9px}.tt-code-feedback header>span{color:#a2464b}.tt-code-feedback header>strong{font-weight:500;overflow-wrap:anywhere}.tt-code-lines{overflow:auto;background:var(--surface,#fafafa);padding:9px 0;border-radius:5px}.tt-code-line,.tt-code-caret{display:grid;grid-template-columns:38px minmax(max-content,1fr);line-height:1.7;font:12px/1.7 var(--font-mono,monospace);min-width:100%;width:max-content}.tt-code-line code,.tt-code-caret code{white-space:pre;padding:0 12px 0 8px;background:transparent;color:inherit;font:inherit}.tt-line-number{text-align:right;padding-right:8px;color:#999;user-select:none}.tt-code-line.is-error{background:#e5484d10;box-shadow:inset 2px 0 #e5484d}.tt-code-line.is-error .tt-line-number,.tt-code-caret{color:#c72b31}.tt-code-hit{background:transparent;color:inherit;text-decoration:underline wavy #c72b31;text-underline-offset:3px;display:inline-block;min-width:.65ch}.tt-code-reason{font-size:12px!important;line-height:1.65!important;color:#a2333a!important;margin:8px 0!important;overflow-wrap:anywhere}.tt-code-reason small{display:block;font:11px var(--font-mono,monospace);color:#888;margin-top:3px}`;}
